40	const FIRST_INSURANCE_PERCENT = 10;
41	
42	// Multiply before dividing: `amount * 1.1` drifts (115.00000000000001) and
43	// Math.ceil turns the drift into a whole extra gold piece. The spec requires
44	// intermediates to stay exact, so every percentage goes through here.
45	const PERCENT_WHOLE = 100;
46	
47	const percentOf = (amount: number, percent: number): number =>
48	  (amount * percent) / PERCENT_WHOLE;
49	
50	// Rounding always favours MHPCO: premiums round up, payouts round down.
51	const roundPremium = (amount: number): number => Math.ceil(amount);
52	
53	const basePremiumOfType = (type: string): number => BASE_PREMIUMS[type];
54	
55	const BLOCK_SIZE = 3;
56	const BLOCK_BASE_PREMIUM = 60;
57	
58	const countByType = (items: Item[]): Map<string, number> => {
59	  const counts = new Map<string, number>();
60	  for (const item of items) {
61	    counts.set(item.type, (counts.get(item.type) ?? 0) + 1);
62	  }
63	  return counts;
64	};
65	
66	const COMPONENT_TYPES = new Set(["rune", "moonstone"]);
67	
68	// A building block is exactly 3 alike components. Blocks are only offered on
69	// components, never on main items, and only at exactly 3 — 4 runes are priced
70	// per item, not as a block plus one.
71	const formsBuildingBlock = (type: string, count: number): boolean =>
72	  COMPONENT_TYPES.has(type) && count === BLOCK_SIZE;
73	
74	// A group of alike items is priced as a building block if it forms one, and
75	// per item otherwise.
76	const groupBasePremiumOf = (type: string, count: number): number =>
77	  formsBuildingBlock(type, count)
78	    ? BLOCK_BASE_PREMIUM
79	    : count * basePremiumOfType(type);
80	
81	// The policy base premium is the sum of the base premiums of each group of
82	// alike items.
83	const policyBasePremiumOf = (items: Item[]): number =>
84	  [...countByType(items)].reduce(
85	    (total, [type, count]) => total + groupBasePremiumOf(type, count),
86	    0,
87	  );
88	
89	// Item-specific surcharges are additive percentages of the affected item's OWN
90	// base premium — they never compound with each other, and never apply to the
91	// policy total.
92	const CURSE_PERCENT = 50;
93	const HIGH_ENCHANTMENT_PERCENT = 30;
94	const HIGH_ENCHANTMENT_THRESHOLD = 5;
95	
96	const isCursed = (item: Item): boolean => item.cursed === true;
97	
98	const isHighlyEnchanted = (item: Item): boolean =>
99	  (item.enchantment ?? 0) >= HIGH_ENCHANTMENT_THRESHOLD;
100	
101	const surchargePercentOf = (item: Item): number =>
102	  (isCursed(item) ? CURSE_PERCENT : 0) +
103	  (isHighlyEnchanted(item) ? HIGH_ENCHANTMENT_PERCENT : 0);
104	
105	const itemSurchargesOf = (items: Item[]): number =>
106	  items.reduce(
107	    (total, item) =>
108	      total + percentOf(basePremiumOfType(item.type), surchargePercentOf(item)),
109	    0,
110	  );
111	
112	const LOYALTY_PERCENT = 20;
113	const LOYALTY_THRESHOLD_YEARS = 2;
114	const FOLLOW_UP_CONTRACT_PERCENT = 15;
115	
116	const isLongStanding = (customer: Customer): boolean =>
117	  customer.yearsWithMHPCO >= LOYALTY_THRESHOLD_YEARS;
118	
119	// Policy-wide modifiers are additive percentages of the policy base premium:
120	// they never compound with each other. A discount is simply a negative
121	// percentage, so surcharges and discounts sum in a single list.
122	const policyModifierPercentOf = (
123	  customer: Customer,
124	  isFollowUpContract: boolean,
125	): number =>
126	  FIRST_INSURANCE_PERCENT +
127	  (isLongStanding(customer) ? -LOYALTY_PERCENT : 0) +
128	  (isFollowUpContract ? -FOLLOW_UP_CONTRACT_PERCENT : 0);
129	
130	const quoteStep = (
131	  step: Step,
132	  customer: Customer,
133	  isFollowUpContract: boolean,
134	): QuoteResult => {
135	  const basePremium = policyBasePremiumOf(step.items);
136	  const policyModifiers = percentOf(
137	    basePremium,
138	    policyModifierPercentOf(customer, isFollowUpContract),
139	  );
140	
141	  return {
142	    premium: roundPremium(
143	      basePremium +
144	        itemSurchargesOf(step.items) +
145	        policyModifiers +
146	        PROCESSING_FEE,
147	    ),
148	  };
149	};
