151	export const runScenario = (scenario: Scenario): ScenarioOutcome => {
152	  let quotesSoFar = 0;
153	  const results = scenario.steps.map((step) => {
154	    const result = quoteStep(step, scenario.customer, quotesSoFar > 0);
155	    quotesSoFar += 1;
156	    return result;
157	  });
158	
159	  return { results };
160	};
