// Every quote after the customer's first is a follow-up contract. While every
// step is a quote, "quotes before this one" is just the step index; once claim
// steps arrive this must count quote steps specifically rather than positions.
export const runScenario = (scenario: Scenario): ScenarioOutcome => ({
  results: scenario.steps.map((step, quotesSoFar) =>
    quoteStep(step, scenario.customer, quotesSoFar > 0),
  ),
});
